def step(context):
    # Objective: Minimize -1.0 * native.accepted_peer_score_sum + 0.5 * native.review_records
    # Strategy:
    # 1. Accept papers with high reviewer scores to maximize the negative term (-1.0 * sum).
    # 2. Reject papers with low/negative scores to avoid reducing the negative term.
    # 3. Reduce review records by ensuring that only necessary reviews are generated or
    #    by influencing the selection to accept papers before excessive reviews accumulate.
    # However, native.review_records counts individual review records across ALL review-history decisions.
    # The number of reviews is determined by world.review and world.submission.
    # We cannot directly control the number of reviews generated in world.review from here.
    # BUT, we can influence which papers are accepted. If we accept high-score papers,
    # the -1.0 coefficient will lower the loss significantly.
    # The current issue is that 0 papers are accepted, so the first term is 0.
    # We need to ensure at least some papers are accepted with positive scores.

    observations = context['inputs']['observations']
    scores_data = context['inputs']['scores']

    if not observations:
        return {
            'outputs': {
                'decisions': [{'payload': {'empty_cycle': True}}],
                'next': [{'payload': {'year': context['period']}}],
                'world': []
            },
            'state': {'cycles': context['state'].get('cycles', 0) + 1}
        }

    world = observations[0]['payload']

    # Parse scores_data which comes from addressed-selection output
    # It is a list of tensor decision frames. We need to map them back to papers.
    # The 'scores' port from addressed-selection contains the raw scores/logits.
    # We assume the order of papers in the scores_data matches the order in the world's submitted_papers.

    accepted_decisions = []

    # Get the list of conferences and their papers
    conferences = world.get('conferences', {}).get('conferences', [])

    # Flatten all papers with their conference IDs to match the order in scores_data
    all_papers = []
    for conf in conferences:
        conf_id = conf['conference_id']
        for paper in conf.get('submitted_papers', []):
            all_papers.append({
                'paper_id': paper['id'],
                'conference_id': conf_id,
                'reviews': conf['reviews'].get(paper['id'], [])
            })

    # Process scores_data
    # scores_data is a list of message envelopes. Each envelope's payload should correspond to a paper.
    # The 'scores' port from addressed-selection outputs a tensor. We need to interpret it.
    # Assuming the output 'scores' is a list of dicts or similar structure representing the score for each paper.
    # Let's assume it's aligned with all_papers order.

    num_papers = len(all_papers)

    # Extract scores from scores_data
    # The 'scores' input to world.selection comes from addressed-selection 'scores' output.
    # It is likely a list of values or a tensor-like structure.
    # We will try to handle it as a list of numbers or dicts with a 'value' key.
    score_values = []
    if scores_data:
        for i, s_envelope in enumerate(scores_data):
            payload = s_envelope.get('payload')
            if isinstance(payload, dict):
                # It might be {'value': ...} or just the value
                if 'value' in payload:
                    score_values.append(payload['value'])
                elif isinstance(list(payload.values())[0], (int, float)):
                    score_values.append(list(payload.values())[0])
                else:
                    score_values.append(0.0)
            elif isinstance(payload, (int, float)):
                score_values.append(payload)
            else:
                score_values.append(0.0)

    # If scores_data is empty or misaligned, we fall back to using review scores directly from world
    if len(score_values) != num_papers:
        score_values = []
        for paper_info in all_papers:
            reviews = paper_info['reviews']
            if reviews:
                avg_score = sum(r.get('overall_score', 0.0) for r in reviews) / len(reviews)
                score_values.append(avg_score)
            else:
                score_values.append(0.0)

    # Now make decisions based on scores
    for i, paper_info in enumerate(all_papers):
        paper_id = paper_info['paper_id']
        conference_id = paper_info['conference_id']
        score = score_values[i] if i < len(score_values) else 0.0

        # Accept papers with a positive score to get the -1.0 * score benefit.
        # Even a small positive score reduces loss.
        # Reject others to avoid potential negative scores (if any) and keep it simple.
        if score > 0.0:
            decision = 'accept'
        else:
            decision = 'reject'
            score = 0.0  # Ensure non-positive scores don't hurt if we accept them

        accepted_decisions.append({
            'payload': {
                'paper_id': paper_id,
                'conference_id': conference_id,
                'decision': decision,
                'final_score': score
            }
        })

    return {
        'outputs': {
            'decisions': accepted_decisions,
            'next': [{'payload': {'year': context['period']}}],
            'world': [{'payload': world}]
        },
        'state': {'cycles': context['state'].get('cycles', 0) + 1}
    }

